```python
def sieve_primes(n: int) -> list[int]:
    """Return all prime numbers <= n in increasing order using the Sieve of Eratosthenes."""
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    primes = [p for p in range(2, n + 1) if is_prime[p]]
    return primes
```

```python
def valid_brackets(s: str) -> bool:
    """
    Checks if the input string s contains well-formed, correctly nested brackets.

    Args:
        s (str): The input string containing brackets and possibly other characters.

    Returns:
        bool: True if every opening bracket has a matching closing bracket in the correct order; False otherwise.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or stack.pop() != bracket_map[char]:
                return False
    return not stack  # True if stack is empty, meaning all brackets were matched
```

