def leftmost_index(arr: list[int], target: int) -> int:
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if arr[mid] < target:
            left = mid + 1
        elif arr[mid] > target:
            right = mid - 1
        else:
            # Found a target, check if it's the leftmost one
            if mid == left or arr[mid - 1] != target:
                return mid
            else:
                right = mid - 1

    return -1
```

