def count_n_queens(n: int) -> int:
    """
    Returns the number of ways to place n queens on an n-by-n chessboard so that no two queens share a row, column or diagonal.

    :param n: The number of queens to place on the chessboard.
    :return: The number of ways to place n queens.
    :raises ValueError: If n is a negative integer.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 1

    def is_safe(board, row, col):
        # Check if the queen can be placed at position (row, col) without attacking any other queens.
        for r in range(row):
            for c in range(n):
                if board[r][c] == 1 and (r == row or c == col or abs(r - row) == abs(c - col)):
                    return False
        return True

    def place_queens(n, row, board):
        # Place queens on the board using backtracking.
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_safe(board, row, col):
                board[row][col] = 1
                count += place_queens(n, row + 1, board)
                board[row][col] = 0  # Backtrack: reset the position if the placement does not lead to a solution.
        return count

    board = [[0] * n for _ in range(n)]
    return place_queens(n, 0, board)
