def fizzbuzz(n: int) -> list[str]:
    """
    Generate a list of strings for integers 1 to n inclusive, applying the FizzBuzz rules
    and returning an empty list if n < 1.
    """
    if n < 1:
        return []
    return [
        "FizzBuzz" if i % 15 == 0 else "Fizz" if i % 3 == 0 else "Buzz" if i % 5 == 0 else str(i)
        for i in range(1, n + 1)
    ]
```

