def run_length_encode(s: str) -> str:
    """Compresses a string using run-length encoding."""
    if not s:
        return s

    encoded = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            encoded.append(s[i-1] + str(count))
            count = 1

    # Append the last run
    encoded.append(s[-1] + str(count))

    return ''.join(encoded)
```

```python
def valid_brackets(s: str) -> bool:
    # Dictionary to store opening brackets
    bracket_map = { '(': ')', '[': ']', '{': '}' }
    opening_brackets = bracket_map.keys()
    closing_brackets = bracket_map.values()
    stack = []

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or bracket_map[stack[-1]] != char:
                return False
            stack.pop()

    return not stack
```

