def flatten(nested):
    """Flatten a nested list and return a flat list of non-list elements in left-to-right order."""
    flat_list = []
    for item in nested:
        if isinstance(item, list):
            flat_list.extend(flatten(item))
        else:
            flat_list.append(item)
    return flat_list
```

