def leftmost_index(arr: list[int], target: int) -> int:
    def binary_search(left, right):
        if left > right:
            return -1
        mid = (left + right) // 2
        if arr[mid] == target:
            if mid == 0 or arr[mid-1] != target:
                return mid
            else:
                return binary_search(left, mid-1)
        elif arr[mid] < target:
            return binary_search(mid + 1, right)
        else:
            return binary_search(left, mid - 1)

    return binary_search(0, len(arr) - 1)
```

