def longest_common_subsequence(a: str, b: str) -> int:
    # Initialize the matrix to store lengths of longest common subsequences
    dp = [[0] * (len(b) + 1) for _ in range(2)]
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                dp[i % 2][j] = dp[(i - 1) % 2][j - 1] + 1
            else:
                dp[i % 2][j] = max(dp[(i - 1) % 2][j], dp[i % 2][j - 1])
    return dp[len(a) % 2][len(b)]
```

```python
def edit_distance(a: str, b: str) -> int:
    # Initialize matrix
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the first row and column
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the rest of the matrix
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

    return dp[m][n]
```

```python
def count_n_queens(n: int) -> int:
    """Return the number of ways to place n queens on an n-by-n chessboard without conflicts.

    Args:
        n (int): The size of the board and the number of queens.

    Returns:
        int: The number of solutions.

    Raises:
        ValueError: If `n` is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    if n == 1:
        return 0

    def solve(board: list, col: int) -> int:
        if col == n:
            return 1
        count = 0
        row = col
        while row >= 0:
            if is_safe(board, row, col):
                board[row] = col
                row -= 1
                count += solve(board, col + 1)
                board[row] = -1
            row += 1
        return count

    def is_safe(board: list, row: int, col: int) -> bool:
        for i in range(n):
            if board[i] == col or abs(i - col) == abs(row - i):
                return False
        return True

    return solve([], 0)
```
